local u21 = {
    ["hexColor"] = function(p1) --[[ Name: hexColor, Line 6 ]]
        local v2 = Color3.fromRGB
        local v3 = bit32.rshift(p1, 16)
        local v4 = bit32.band(v3, 255)
        local v5 = bit32.rshift(p1, 8)
        return v2(v4, bit32.band(v5, 255), (bit32.band(p1, 255)))
    end,
    ["richTextColor"] = function(p6) --[[ Name: richTextColor, Line 11 ]]
        local v7 = p6.R * 255
        local v8 = math.round(v7)
        local v9 = tostring(v8)
        local v10 = p6.G * 255
        local v11 = math.round(v10)
        local v12 = tostring(v11)
        local v13 = p6.B * 255
        local v14 = math.round(v13)
        return "rgb(" .. v9 .. "," .. v12 .. "," .. tostring(v14) .. ")"
    end,
    ["richTextColorWrap"] = function(p15, p16) --[[ Name: richTextColorWrap, Line 16 ]]
        --[[
        Upvalues:
            [1] = u21
        --]]
        return "<font color=\"" .. u21.richTextColor(p15) .. "\">" .. p16 .. "</font>"
    end,
    ["darken"] = function(p17, p18) --[[ Name: darken, Line 26 ]]
        return Color3.new(p17.R * p18, p17.G * p18, p17.B * p18)
    end,
    ["brighten"] = function(p19, p20) --[[ Name: brighten, Line 36 ]]
        return Color3.new(p20 + (1 - p20) * p19.R, p20 + (1 - p20) * p19.G, p20 + (1 - p20) * p19.B)
    end
}
u21.BLACK = u21.hexColor(0)
